    if (src == NULL || dest == NULL)
        return;

    const char *src_ptr = src;
    int count = 0;

    while (*src_ptr != '\0') {
        char current = *src_ptr;
        count = 1;
        while (src_ptr[1] != '\0' && src_ptr[1] == current) {
            src_ptr++;
            count++;
        }
        // Write the character, then write ASCII digits of count
        *dest++ = current;

        // Since max consecutive runs fit in int, write count as string
        if (count > 9) {
